class WorkerClient {
  constructor(){this.pending=new Map();this.nextId=0;const embedded=globalThis.__LATTICE_WORKER_SOURCE__;this.url=embedded?URL.createObjectURL(new Blob([embedded],{type:'text/javascript'})):new URL('./worker.js',import.meta.url);this.worker=new Worker(this.url,{type:embedded?'classic':'module',name:'lattice-query-engine'});this.worker.onmessage=({data})=>{const p=this.pending.get(data.id);if(!p)return;clearTimeout(p.timer);this.pending.delete(data.id);if(data.error)p.reject(new Error(data.error.message));else p.resolve(data.value);};this.worker.onerror=e=>{for(const p of this.pending.values()){clearTimeout(p.timer);p.reject(new Error(e.message||'The analytics worker stopped.'));}this.pending.clear();};}
  call(method,args={}){return new Promise((resolve,reject)=>{const id=++this.nextId;const timer=setTimeout(()=>{this.pending.delete(id);reject(new Error(`${method} exceeded the 120-second worker deadline.`));},120000);this.pending.set(id,{resolve,reject,timer});this.worker.postMessage({id,method,args});});}
  dispose(){this.worker.terminate();for(const p of this.pending.values())clearTimeout(p.timer);if(typeof this.url==='string')URL.revokeObjectURL(this.url);}
}
class LocalStore {
  async open(){try{this.db=await new Promise((resolve,reject)=>{const req=indexedDB.open('lattice-analytics-v1',1);req.onupgradeneeded=()=>{req.result.createObjectStore('metadata');req.result.createObjectStore('sources',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return true;}catch{this.db=null;return false;}}
  async read(store,key){if(!this.db)return null;return new Promise((resolve,reject)=>{const tx=this.db.transaction(store),r=tx.objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
  async save(workbook,sources){if(!this.db)throw new Error('Browser storage is unavailable. Export a workbook file to save your work.');return new Promise((resolve,reject)=>{const tx=this.db.transaction(sources?['metadata','sources']:['metadata'],'readwrite');tx.objectStore('metadata').put(structuredClone(workbook),'current');if(sources)for(const source of sources)tx.objectStore('sources').put(source);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error??new Error('Storage transaction aborted.'));});}
}
const rpc=new WorkerClient(),store=new LocalStore(),history=new WorkbookHistory();
let workbook=null,selection=null,views=new Map(),results=new Map(),renderEpoch=0,queryEpoch=0,saveTimer=null,dataDirty=false,saveInFlight=null,saveVersion=0;
