function showMenu(anchor,items){closeMenu();const menu=document.createElement('div');menu.className='context-menu';for(const item of items){if(item==='-'){menu.append(document.createElement('hr'));continue;}if(item.heading){const label=document.createElement('div');label.className='context-label';label.textContent=item.heading;menu.append(label);continue;}if(item.note){const note=document.createElement('p');note.textContent=item.note;menu.append(note);continue;}const button=document.createElement('button');button.type='button';button.className=`${item.active?'active':''} ${item.danger?'danger':''}`;button.innerHTML=`<span>${esc(item.label)}</span>${item.shortcut?`<small>${esc(item.shortcut)}</small>`:''}`;button.disabled=!!item.disabled;button.onclick=()=>{closeMenu();Promise.resolve(item.action?.()).catch(fail);};menu.append(button);}$('#menu-root').append(menu);const rect=anchor instanceof Element?anchor.getBoundingClientRect():{left:anchor.x,bottom:anchor.y};menu.style.left=Math.max(6,Math.min(rect.left,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(6,Math.min(rect.bottom+4,innerHeight-menu.offsetHeight-8))+'px';}
