    showModal(`Filter: ${field}`,`<p>Keep source rows in this inclusive range. The filter runs <strong>before aggregation</strong>.</p><div class="form-row"><label><span>Minimum</span><input type="${inputType}" id="filter-min" value="${fmt(existing?.min)}" placeholder="${fmt(info.min)}" ${isDate?'':'step="any"'}></label><label><span>Maximum</span><input type="${inputType}" id="filter-max" value="${fmt(existing?.max)}" placeholder="${fmt(info.max)}" ${isDate?'':'step="any"'}></label></div><div class="help-text">Source range: ${esc(fmt(info.min))} to ${esc(fmt(info.max))} · ${count(info.nulls)} null values.<br>Empty bounds are unbounded. A range filter excludes nulls.</div>`,{buttons:[{text:'Remove filter',action:()=>apply(null)},{text:'Cancel',action:closeModal},{text:'Apply filter',primary:true,action:()=>{const a=$('#filter-min').value,b=$('#filter-max').value,min=a===''?null:isDate?Date.parse(a):Number(a),max=b===''?null:isDate?Date.parse(b)+86399999:Number(b);if(min!=null&&max!=null&&min>max)throw new Error('The minimum cannot exceed the maximum.');apply({field,op:'between',min,max});}}]});return;
