  $('#calc-expression').oninput=()=>{clearTimeout(debounce);$('#calc-apply').disabled=true;debounce=setTimeout(validate,180);};$$('[data-function]').forEach(button=>button.onclick=()=>{const input=$('#calc-expression'),f=button.dataset.function,text=f==='IF'?'IF condition THEN value ELSE value END':f+'()';input.setRangeText(text,input.selectionStart,input.selectionEnd,'end');input.focus();validate();});await validate();
