async function exportWorkbook(){const snapshots=await rpc.call('snapshot'),ids=new Set(workbook.sources.map(s=>s.id));const file={...structuredClone(workbook),exportedAt:new Date().toISOString(),datasets:snapshots.filter(s=>ids.has(s.id))};download(`${safeFilename(workbook.name)}.lattice`,JSON.stringify(file),'application/json');toast('Portable workbook exported with data, calculations, sheets, and layouts.','success');}
async function openWorkbook(file){if(!file)return;const json=JSON.parse(await file.text());validateWorkbook(json);if(!Array.isArray(json.datasets)||json.sources.some(s=>!json.datasets.some(d=>d.id===s.id)))throw new Error('This workbook is missing its source datasets.');const {datasets,...metadata}=json;for(const source of metadata.sources){const data=datasets.find(d=>d.id===source.id);data.definitions=source.definitions??[];}await rpc.call('restore',{sources:datasets});workbook=metadata;history.clear();selection=null;focusedSheetId=null;await syncDefinitions();markChanged(true);renderAll();$('#workbook-file-input').value='';toast(`Opened “${workbook.name}”.`,'success');}
function exportSVG(viewId){const view=viewId?views.get(viewId):[...views.values()].find(v=>v.sheetId===activeSheet()?.id)??views.values().next().value;if(!view)throw new Error('Open a worksheet or dashboard before exporting a chart.');const name=sheetById(view.sheetId)?.name??'Chart';download(`${safeFilename(name)}.svg`,view.chart.toSVG(name),'image/svg+xml');toast('Exported the visualization as editable SVG.','success');}
function exportDialog(){const s=activeSheet();showModal('Export your work',`<p>Your data stays in this browser until you choose to export it.</p><label class="form-field"><span>Format</span><select id="export-format"><option value="workbook">Lattice workbook · all data and editable views</option><option value="csv-results">CSV · active worksheet query results</option><option value="json-results">JSON · active worksheet query results</option><option value="csv-source">CSV · full active data source</option><option value="json-source">JSON · full active data source</option><option value="svg">SVG · active visualization</option></select></label><div class="help-text">Worksheet exports contain the grouped or raw marks currently queried, including filters and the mark limit. Source exports contain all source records, including materialized calculations.<br><br>CSV exports preserve values exactly. Treat untrusted text beginning with spreadsheet formula characters as text when opening it in spreadsheet software.</div>`,{buttons:[{text:'Cancel',action:closeModal},{text:'Export',primary:true,action:async()=>{const format=$('#export-format').value;if(format==='workbook')await exportWorkbook();else if(format==='svg')exportSVG();else{let rows,name;if(format.endsWith('results')){if(!s||!results.has(s.id))throw new Error('Open a worksheet first.');const cached=results.get(s.id);rows=humanizeResults(cached);name=s.name;}else{rows=await rpc.call('export',{tableId:activeSource().id});name=activeSource().name;}const json=format.startsWith('json');download(`${safeFilename(name)}.${json?'json':'csv'}`,json?JSON.stringify(rows,null,2):toCSV(rows),json?'application/json':'text/csv;charset=utf-8');toast(`Exported ${count(rows.length)} records.`,'success');}closeModal();}}]});}
function humanizeResults(cached){return cached.result.rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>{const m=cached.spec.measures.find(m=>m.as===k);return [m?`${cached.spec.raw?'':m.op.toUpperCase()+'('}${m.field==='*'?'Records':m.field}${cached.spec.raw?'':')'}`:k==='__rowId'?'Source row index':k,v];})));}
function dataTableHTML(rows,schema){const columns=schema?.map(f=>f.name)??Object.keys(rows[0]??{});if(!columns.length)return '<div class="help-text" style="padding:20px">No records matched the current query.</div>';return `<table class="data-table"><thead><tr><th>#</th>${columns.map(name=>`<th>${esc(name)}</th>`).join('')}</tr></thead><tbody>${rows.map((row,i)=>`<tr><td style="color:#b8afc2">${i+1}</td>${columns.map(name=>`<td class="${typeof row[name]==='number'?'numeric ':''}${row[name]==null?'null':''}" title="${esc(row[name]??'NULL')}">${esc(row[name]??'NULL')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
async function previewData(offset=0){const source=activeSource(),result=await rpc.call('preview',{tableId:source.id,offset,limit:100});showModal(`Data preview · ${source.name}`,`<div class="table-meta"><span>Rows ${result.rows.length?offset+1:0}–${Math.min(offset+100,result.total)} of ${count(result.total)}</span><span>${result.schema.length} fields · Worker-backed columnar data</span></div><div class="data-table-container">${dataTableHTML(result.rows,result.schema)}</div><p class="help-text">Dates use ISO 8601; nulls are shown explicitly. Calculated and grouped fields appear alongside imported columns.</p>`,{wide:true,buttons:[{text:'Previous 100',disabled:offset===0,action:()=>previewData(Math.max(0,offset-100))},{text:'Next 100',disabled:offset+100>=result.total,action:()=>previewData(offset+100)},{text:'Close',primary:true,action:closeModal}]});}
function previewResults(id=activeSheet()?.id){const cached=results.get(id);if(!cached)throw new Error('No query results yet. Open a worksheet first.');const rows=humanizeResults(cached);showModal(`Query results · ${sheetById(id).name}`,`<div class="table-meta"><span>${count(rows.length)} result records · ${count(cached.result.stats.matchedRows)} matched source rows</span><span>Showing first ${Math.min(500,rows.length)} records</span></div><div class="data-table-container">${dataTableHTML(rows.slice(0,500))}</div>`,{wide:true,buttons:[{text:'Export CSV',action:()=>download(`${safeFilename(sheetById(id).name)}.csv`,toCSV(rows),'text/csv;charset=utf-8')},{text:'Close',primary:true,action:closeModal}]});}
async function renderDataSource(){const epoch=renderEpoch,source=activeSource();$('#workspace-content').innerHTML=`<div class="data-source-view"><div class="dashboard-eyebrow">${icon('database')} Data workspace</div><h1>Your data, connected.</h1><p>Inspect local extracts, combine sources, and build reusable calculations.</p><div class="source-actions"><button class="btn" data-action="import">${icon('database')}Connect data</button><button class="btn" data-action="join">${icon('join')}Join sources</button><button class="btn" data-action="append">${icon('refresh')}Append records</button><button class="btn" data-action="calculation">ƒx Calculated field</button></div><div class="source-nodes">${workbook.sources.map(s=>`<button class="source-node ${source.id===s.id?'active':''}" data-select-source="${esc(s.id)}"><strong>${icon('database')} ${esc(s.name)}</strong><span>${count(s.rows)} rows · ${s.schema.length} columns · ${formatNumber(s.bytes/1048576)} MB</span></button>`).join('')}</div><div class="table-meta"><span>${esc(source.name)} · First 100 records</span><button data-action="preview" style="font-size:10px;color:#a58ab8">Open paginated preview ↗</button></div><div class="data-table-container" id="source-table"><div style="padding:20px" class="help-text">Reading typed columns…</div></div><div class="table-meta"><span>${source.sample?'Synthetic demonstration data. Every chart is computed from the source rows.':'Imported data stays local. No network requests are made by the analytics engine.'}</span></div>${source.joinStats?`<div class="inline-alert">Join: ${count(source.joinStats.leftRows)} left × ${count(source.joinStats.rightRows)} right → ${count(source.joinStats.outputRows)} output rows. ${count(source.joinStats.unmatchedLeft)} unmatched left keys, ${count(source.joinStats.unmatchedRight)} unmatched right rows.</div>`:''}</div>`;try{const data=await rpc.call('preview',{tableId:source.id,limit:100});if(epoch===renderEpoch&&$('#source-table'))$('#source-table').innerHTML=dataTableHTML(data.rows,data.schema);}catch(e){fail(e);}$('#status-marks').textContent=`${source.schema.length} fields`;$('#status-rows').textContent=`${count(source.rows)} source rows`;$('#query-status').textContent=`${formatNumber(source.bytes/1048576)} MB columnar storage`;}
function sourceInfo(){const source=activeSource();showModal(`Source information · ${source.name}`,`<div class="plan-stats"><div><b>${count(source.rows)}</b>rows</div><div><b>${source.schema.length}</b>typed columns</div><div><b>${formatNumber(source.bytes/1048576)} MB</b>column buffers + dictionaries</div><div><b>${source.definitions.length}</b>derived fields</div></div><div class="data-table-container"><table class="data-table"><thead><tr><th>Field</th><th>Type</th><th>Role</th><th>Nulls</th><th>Storage</th></tr></thead><tbody>${source.schema.map(f=>`<tr><td>${esc(f.name)}</td><td>${f.type}</td><td>${fieldInfo(source,f.name).role}</td><td>${count(f.nulls??0)}</td><td>${f.type==='string'?'Uint32 dictionary codes':f.type==='boolean'?'Uint8':'Float64'} + validity</td></tr>`).join('')}</tbody></table></div><p class="help-text">Memory shown excludes query caches, worker message copies, and JavaScript object overhead. Numeric precision is IEEE 754 double precision; this is not a fixed-decimal accounting engine.</p>`,{wide:true});}
function analysisDialog(id=activeSheet()?.id){const c=results.get(id);if(!c)throw new Error('Open a worksheet to inspect its executed plan.');const {stats}=c.result;showModal(`Query plan · ${sheetById(id).name}`,`<div class="plan-stats"><div><b>${stats.elapsed.toFixed(2)} ms</b>worker query time</div><div><b>${count(stats.scannedRows)}</b>rows scanned this run</div><div><b>${count(stats.matchedRows)}</b>rows matched in total</div><div><b>${esc(stats.mode)}</b>aggregation state</div></div>${c.result.plan.map((p,i)=>{const {operator,...detail}=p;return `<div class="plan-operator"><header><span>${i+1}</span>${operator}</header><pre>${esc(JSON.stringify(detail,null,2))}</pre></div>`;}).join('')}<p class="help-text">Row filters run before aggregation. Sort and limit run after aggregation. A cache hit scans zero rows; an append-only update scans the new suffix. Derived-field changes invalidate affected source caches. Query time excludes worker messaging, chart layout, and GPU submission.</p>`,{wide:true,buttons:[{text:'Export plan JSON',action:()=>download('query-plan.json',JSON.stringify({spec:c.spec,plan:c.result.plan,stats},null,2),'application/json')},{text:'Close',primary:true,action:closeModal}]});}
function helpDialog(){showModal('A little guidance. A lot of possibility.',`<div class="shortcut-grid"><span>Save workbook locally</span><span><kbd>Ctrl / ⌘</kbd> <kbd>S</kbd></span><span>Open a portable workbook</span><span><kbd>Ctrl / ⌘</kbd> <kbd>O</kbd></span><span>Undo / Redo</span><span><kbd>Ctrl / ⌘ Z</kbd> / <kbd>Shift Z</kbd></span><span>Clear linked selection</span><span><kbd>Esc</kbd></span><span>Multi-select chart marks</span><span><kbd>Ctrl / ⌘</kbd> + click</span><span>Brush a scatter plot</span><span><kbd>Shift</kbd> + drag</span><span>Add a field automatically</span><span>Double-click a field</span></div><div class="workbook-info"><strong>Build a worksheet</strong><br>Drag a dimension to Rows and a measure to Columns. Use the pill menu to change aggregation. Add Color, Size, Label, or Detail. Drop any field on Filters.<br><br><strong>Connect your views</strong><br>Open a dashboard and click a mark to filter other worksheets using the same source. “Edit layout” enables tile moving and resizing on a 12-column grid. Add worksheets from the right pane while editing.<br><br><strong>Make it yours</strong><br>Import CSV/JSON, create typed calculated fields, group members, or materialize inner/left/full joins. Changes are undoable. Data and workbook metadata are saved to IndexedDB; export a .lattice file for a portable copy.</div><p class="help-text">Lattice is an original, independent implementation inspired by desktop visual analytics workflows. It does not read Tableau .twb/.twbx files or connect to Tableau Server. The included retail data is synthetic.</p><p class="help-text">WebGPU is used when available. Canvas2D is an explicitly identified fallback. Desktop keyboard and mouse are recommended for authoring; dashboard views can also be inspected with touch.</p>`,{wide:false});}

const actions={
  undo:()=>historyStep('undo'),redo:()=>historyStep('redo'),save:()=>saveLocal(),import:()=>$('#data-file-input').click(),append:()=>$('#append-file-input').click(),
  'new-sheet':createWorksheet,'duplicate-sheet':()=>duplicateWorksheet(),'clear-sheet':clearWorksheet,swap:swapShelves,
  'sort-asc':()=>activeSheet()&&mutate('sort ascending',()=>activeSheet().sort='asc'),'sort-desc':()=>activeSheet()&&mutate('sort descending',()=>activeSheet().sort='desc'),
  calculation:()=>calculationDialog(),group:()=>groupDialog(),join:joinDialog,export:exportDialog,
  'new-dashboard':createDashboard,'edit-dashboard':toggleDashboardEdit,'clear-selection':clearSelection,
  'toggle-show-me':()=>{$('#right-pane').classList.toggle('hidden');$('#show-me-toggle').classList.toggle('active');},
  'data-tab':()=>{analyticsTab=false;renderFields();},'analytics-tab':()=>{analyticsTab=true;renderFields();},
  preview:()=>previewData(),'preview-results':()=>previewResults(),'source-info':sourceInfo,
  'data-source':()=>setActive('data',activeSource().id),analysis:()=>analysisDialog(),format:()=>{$('#right-pane').classList.remove('hidden');renderRightPane();},
  help:helpDialog,'sheet-menu':e=>worksheetMenu(e.target.closest('button'))
};
document.addEventListener('click',e=>{
  const action=e.target.closest('[data-action]');if(action){e.preventDefault();Promise.resolve().then(()=>actions[action.dataset.action]?.(e)).catch(fail);return;}
  const menu=e.target.closest('[data-menu]');if(menu){({file:fileMenu,data:dataMenu,worksheet:worksheetMenu,dashboard:dashboardMenu})[menu.dataset.menu]?.(menu);return;}
  const fieldOption=e.target.closest('.field-options');if(fieldOption){fieldMenu(fieldOption,fieldOption.closest('[data-field]').dataset.field);return;}
  const pill=e.target.closest('.field-pill');if(pill){if(e.target.closest('.pill-remove'))removePill(pill.dataset.pillSlot,+pill.dataset.pillIndex);else if(e.target.closest('.pill-menu'))pillMenu(pill,pill.dataset.pillSlot,+pill.dataset.pillIndex);else if(pill.dataset.filterIndex!=null){const i=+pill.dataset.filterIndex;filterDialog(activeSheet().filters[i].field,i).catch(fail);}return;}
  const open=e.target.closest('[data-open-sheet]');if(open){setActive('sheet',open.dataset.openSheet);return;}
  const dash=e.target.closest('[data-open-dashboard]');if(dash){setActive('dashboard',dash.dataset.openDashboard);return;}
  const chartType=e.target.closest('[data-chart-type]');if(chartType){changeChartType(chartType.dataset.chartType);return;}
  const markSlot=e.target.closest('[data-choose-mark]');if(markSlot){chooseMarkField(markSlot,markSlot.dataset.chooseMark);return;}
  const tile=e.target.closest('[data-tile-menu]');if(tile){tileMenu(tile,tile.dataset.tileMenu);return;}
  const addTile=e.target.closest('[data-add-tile]');if(addTile){addDashboardTile(addTile.dataset.addTile);return;}
  const selectSource=e.target.closest('[data-select-source]');if(selectSource){mutate('select data source',()=>{workbook.activeSource=selectSource.dataset.selectSource;workbook.active={kind:'data',id:workbook.activeSource};});return;}
  if(!e.target.closest('.context-menu'))closeMenu();
});
document.addEventListener('dblclick',e=>{const field=e.target.closest('.field-item');if(field)try{autoAddField(field.dataset.field,field.dataset.source);}catch(err){fail(err);}});
document.addEventListener('contextmenu',e=>{const field=e.target.closest('.field-item'),tab=e.target.closest('[data-open-sheet]');if(field){e.preventDefault();fieldMenu({x:e.clientX,y:e.clientY},field.dataset.field);}else if(tab){e.preventDefault();worksheetMenu({x:e.clientX,y:e.clientY},sheetById(tab.dataset.openSheet));}});
document.addEventListener('dragstart',e=>{const field=e.target.closest('[draggable=true][data-field]');if(!field)return;const data={field:field.dataset.field,source:field.dataset.source,from:field.dataset.pillSlot?{slot:field.dataset.pillSlot,index:+field.dataset.pillIndex,sheet:field.dataset.sheet}:null};e.dataTransfer.setData('application/x-lattice-field',JSON.stringify(data));e.dataTransfer.setData('text/plain',field.dataset.field);e.dataTransfer.effectAllowed=field.dataset.pillSlot?'move':'copy';});
document.addEventListener('dragover',e=>{const target=e.target.closest('.drop-target');if(target){e.preventDefault();e.dataTransfer.dropEffect='copy';target.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>{const target=e.target.closest('.drop-target');if(target&&!target.contains(e.relatedTarget))target.classList.remove('drag-over');});
document.addEventListener('dragend',()=>$$('.drag-over').forEach(e=>e.classList.remove('drag-over')));
document.addEventListener('drop',e=>{const target=e.target.closest('.drop-target');$$('.drag-over').forEach(e=>e.classList.remove('drag-over'));if(!target)return;e.preventDefault();try{const text=e.dataTransfer.getData('application/x-lattice-field');if(!text)return;const data=JSON.parse(text);addField(data.field,target.dataset.drop,data.source,data.from);}catch(error){fail(error);}});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){closeMenu();if(!$('#modal').open&&selection)clearSelection();return;}
  const typing=e.target instanceof HTMLElement&&e.target.matches('input,textarea,select,[contenteditable=true]');
  if((e.ctrlKey||e.metaKey)&&['s','o','z','y'].includes(e.key.toLowerCase())){const key=e.key.toLowerCase();if((key==='z'||key==='y')&&(typing||$('#modal').open))return;e.preventDefault();if(key==='s')saveLocal().catch(fail);else if(key==='o')$('#workbook-file-input').click();else historyStep(key==='y'||e.shiftKey?'redo':'undo').catch(fail);}
  if(e.key==='Enter'&&e.target.closest('.field-item')){const el=e.target.closest('.field-item');autoAddField(el.dataset.field,el.dataset.source);}
});
$('#field-search').addEventListener('input',e=>{fieldSearch=e.target.value;renderFields();});
$('#source-select').addEventListener('change',e=>mutate('select data source',()=>{workbook.activeSource=e.target.value;if(workbook.active.kind==='data')workbook.active.id=e.target.value;}));
$('#fit-mode').addEventListener('change',e=>{const content=$('#workspace-content');content.style.zoom=e.target.value==='compact'?'.86':'1';$('#right-pane').classList.toggle('hidden',e.target.value==='wide');});
$('#data-file-input').addEventListener('change',e=>importFiles([...e.target.files]).catch(fail));
$('#append-file-input').addEventListener('change',e=>appendFile(e.target.files[0]).catch(fail));
$('#workbook-file-input').addEventListener('change',e=>openWorkbook(e.target.files[0]).catch(fail));
$('#modal-close').onclick=closeModal;$('#modal-form').addEventListener('submit',e=>e.preventDefault());
$('#help-button').onclick=helpDialog;$('.brand').onclick=e=>{e.preventDefault();const d=workbook?.dashboards[0];if(d)setActive('dashboard',d.id);};
$('#workbook-name').ondblclick=()=>inputDialog('Rename workbook','Workbook name',workbook.name,name=>mutate('rename workbook',()=>workbook.name=name));
window.addEventListener('beforeunload',()=>rpc.dispose());
window.addEventListener('error',e=>{if(workbook&&e.message)toast(`Application error: ${e.message}`,'error');});
async function boot(){
  $$('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon));
  for(const [action,name]of Object.entries({undo:'undo',redo:'redo',save:'save','new-sheet':'sheet','duplicate-sheet':'duplicate','clear-sheet':'clear',swap:'swap','sort-asc':'sort-asc','sort-desc':'sort-desc',group:'group',join:'join'})){const button=$(`.toolbar [data-action="${action}"]`);if(button)button.innerHTML=icon(name);}
  const available=await store.open();let restored=false;
  if(available){try{const metadata=await store.read('metadata','current');if(metadata){validateWorkbook(metadata);const sources=await Promise.all(metadata.sources.map(s=>store.read('sources',s.id)));if(sources.some(s=>!s))throw new Error('Saved source data is missing.');for(const s of sources)s.definitions=metadata.sources.find(x=>x.id===s.id).definitions??[];await rpc.call('restore',{sources});workbook=metadata;restored=true;await syncDefinitions();}}catch(error){toast(`Saved workbook could not be restored: ${error.message}. Opening a fresh sample.`,'error');}}
  if(!restored)await initializeSample();focusedSheetId=workbook.active.kind==='sheet'?workbook.active.id:activeDashboard()?.tiles[0]?.sheetId??workbook.sheets[0]?.id;
  renderAll();$('#boot-screen').classList.add('dismiss');setTimeout(()=>$('#boot-screen').remove(),350);
  if(available){await saveLocal(false);}else{$('#saved-indicator').textContent='File export available';toast('Browser storage is blocked. Use File → Download workbook to keep your changes.');}
  // Diagnostics for reproducible browser tests and performance inspection.
  Object.defineProperty(globalThis,'latticeDebug',{value:Object.freeze({get workbook(){return structuredClone(workbook);},get selection(){return selection?structuredClone(selection):null;},get results(){return new Map(results);},get renderer(){return currentMode;},get viewCount(){return views.size;}})});
}
boot().catch(error=>{fail(error);$('#boot-screen').innerHTML=`<div class="boot-mark">!</div><h1>The workspace could not start.</h1><p style="max-width:560px;text-align:center;line-height:1.7">${esc(error.message)}</p><p>Serve the project over localhost, or open the bundled lattice.html file.</p><button class="btn primary" onclick="location.reload()">Try again</button>`;});
